SELECT b.sha256 FROM attachment_blobs b
WHERE NOT EXISTS(SELECT 1 FROM attachments a WHERE a.blob_sha256=b.sha256 AND a.status IN ('DRAFT','BOUND'))
ORDER BY b.created_at,b.sha256 LIMIT #{limit}

mapper.update:
UPDATE thread_title_generations SET result=#{result},input_tokens=#{inputTokens},output_tokens=#{outputTokens},
  total_tokens=#{totalTokens},failure_code=#{failureCode},completed_at=#{completedAt}
WHERE generation_id=#{generationId} AND result IS NULL
